<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;class StoreTrainingNeedRequest extends FormRequest{public function authorize(){return$this->user()?->can('capacitaciones.necesidades.crear')??false;}public function rules(){return['title'=>'required|string|max:255','description'=>'required|string|max:4000','origin_type'=>['required',Rule::in(array_keys(config('training.need_origins')))],'origin_description'=>'nullable|string|max:2000','priority'=>'required|in:low,medium,high,critical','identified_at'=>'required|date','required_by'=>'nullable|date|after_or_equal:identified_at','target_population_type'=>['required',Rule::in(array_keys(config('training.population_types')))],'target_population_description'=>'required|string|max:2000','identified_by'=>'nullable|exists:empleados,id','risk_ids'=>'nullable|array','risk_ids.*'=>'exists:matriz_riesgos,id'];}}
